import assert from 'node:assert/strict';
import {createController} from './src/controller.js';
const pending=[];const records=[];const views=[];
const c=createController({service:{commit(snapshot){return new Promise((resolve,reject)=>pending.push({snapshot,resolve,reject}));}},audit:{record:x=>records.push(x)},render:x=>views.push(x)});
c.open('old','alice');c.edit('first');const first=c.submit();c.edit('second');const second=c.submit();
assert.ok(first instanceof Promise);assert.deepEqual(pending.map(x=>x.snapshot),[{doc:'old',actor:'alice',text:'first'},{doc:'old',actor:'alice',text:'second'}]);
pending[0].resolve({revision:1});await first;assert.deepEqual(views,[]);
pending[1].reject(new Error('failed'));await second;assert.deepEqual(views,[{status:'error',doc:'old'}]);assert.deepEqual(records,[{doc:'old',actor:'alice',text:'first',revision:1}]);
c.edit('third');const third=c.submit();c.close();c.open('new','bob');pending[2].resolve({revision:3});await third;assert.equal(views.length,1);assert.deepEqual(records[1],{doc:'old',actor:'alice',text:'third',revision:3});
const thrown=createController({service:{commit(){throw Error('sync');}},audit:{record(){throw Error('unexpected audit');}},render:x=>views.push(x)});thrown.open('x','y');await thrown.submit();assert.deepEqual(views.at(-1),{status:'error',doc:'x'});
assert.equal(c.close(),undefined);assert.equal(c.submit(),null);
console.log('controller async checks passed');
EOF"

